ROW.COLUMN:
-- jainanu on 29th July'09 - While PR 39635: Corrected implementation of PR 31681
select wt.FO_TRXN_SEQ_ID -- Dataset Key ID ------------------ ,c.CUST_INTRL_ID -- Pair Internal Entity Identification ,ee.EXTRL_NTITY_SEQ_ID -- Pair External Entity Identification -- -- This fields from the WIRE_TRXN-table -- we'll be needed for father calculations -- ,a.ACCT_INTRL_ID as ORIG_ACCT_ID ,wt.SCND_ORIG_ACTVY_RISK_NB as ORIG_ACTVY_RISK_NB ,wt.SCND_ORIG_NTITY_RISK_NB as ORIG_NTITY_RISK_NB ,wt.PASS_THRU_FL ,wt.TRXN_BASE_AM ,wt.RCV_TRXN_ACTVY_AM ,wt.SEND_TRXN_ACTVY_AM ,c.CUST_EFCTV_RISK_NB -- we'll be needed DATA_DUMP_DT -- for Frequency Period check ,wt.DATA_DUMP_DT from
@BUSINESS@.CUST c, @BUSINESS@.ACCT a, @BUSINESS@.WIRE_TRXN wt, @BUSINESS@.EXTERNAL_ENTITY ee where --BUG21688010 a.PRMRY_CUST_INTRL_ID = c.CUST_INTRL_ID and a.ACCT_INTRL_ID = wt.SCND_ORIG_ACCT_ID and (ee.EXTRL_NTITY_SEQ_ID = wt.SCND_BENEF_EXTRL_NTITY_SEQ_ID or wt.SCND_BENEF_AUG_NM = ee.EXTRL_NTITY_NM) -- Include transactions only within the look back period --BUG21688010 and wt.TRXN_EXCTN_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) -- PR24019 : add the data_dump_dt in checking the lokk back period -- as same as the trxn_extn_dt to utilize index. and wt.DATA_DUMP_DT in (select cal.clndr_dt from @MANTAS@.KDD_cal cal where cal.CLNDR_NM = 'SYSCAL' and cal.CLNDR_DAY_AGE between 0 and @Look_Back_Period - 1) -- Make shure, that SECONDERY Orig is not the same Entity, as Orig -- PR31681 and wt.SCND_ORIG_ACCT_ID <> coalesce(wt.ORIG_ACCT_ID,'-1') -- Get from the transaction table only records -- were ORIG is INTERNAL and BENEF is EXTERNAL and wt.INTRL_SCND_ORIG_ACCT_FL = 'Y' and wt.INTRL_SCND_BENEF_ACCT_FL <> 'Y' -- Make shure, that SECONDERY Benef is not the same Entity, as Benef -- include transaction record where SCND_BENEF <> BENEF -- PR31681/39635 and (wt.INTRL_BENEF_ACCT_FL ='Y' or ( (ee.EXTRL_NTITY_NM is null and coalesce(wt.BENEF_EXTRL_NTITY_SEQ_ID, -1) <> wt.SCND_BENEF_EXTRL_NTITY_SEQ_ID) or (ee.EXTRL_NTITY_NM is not null and coalesce(wt.BENEF_AUG_NM, '-') <> wt.SCND_BENEF_AUG_NM))) -------------------------------------------------------------- -- Filter : Retail Customer Accounts and a.MANTAS_ACCT_HOLDR_TYPE_CD = 'CR' -- Include Account Business Types Specified in Mantas Business Acct Types Parameter and a.MANTAS_ACCT_BUS_TYPE_CD in (@Mantas_Bus_Acct_Type_Lst) -- Include all Customers when All Jurisdictions is set to 'Y' or -- Customers with jurisdiction only specified in Included Jurisdiction Codes Parameter and (@All_Jurisdictions_Fl = 'Y' or c.JRSDCN_CD in (@Incl_Jurisdictions_Lst)) and c.CUST_EFCTV_RISK_NB <> -2 -- " Exclude Exempt Customers --Included Transaction Source Codes or All Transaction Sources and (wt.SRC_SYS_CD in (@Incl_Trans_Src_Lst) or @All_Trans_Src_Fl = 'Y') -- Filter : Electronic Funds Transactions and wt.MANTAS_TRXN_PRDCT_CD in (@Incl_Wire_Trxn_Prdct_Type_Lst) -- Mantas data structure modification : --The filter MANTAS_TRXN_PURP_CD = 'GENERAL' needs to be paired with --MANTAS_TRXN_PRDCT_CD filter in the datasets for all MLM scenarios and wt.MANTAS_TRXN_PURP_CD = 'GENERAL' and (@Incl_Rltd_Parties ='Y' or coalesce (wt.UNRLTD_PARTY_FL,'Y') <>'N') --21034264 and (@Include_Trusted_Trans_FL = 'Y' or COALESCE(wt.TRSTD_TRXN_FL, 'N') = 'N')
